package net.officefloor.hq.app.sheet;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.UncheckedIOException;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet as it stood after each change, so it can be shown as of a date. After every change the
 * whole of the sheet's stored rows are kept (in {@code sheet_snapshot}) with the sheet's today then;
 * {@link #restore} puts the last one made on or before a date back in place of the sheet's rows,
 * its today the date, for the caller's transaction to read and then roll back.
 *
 * <p>The sheet's rows are found from the schema: every table with a {@code sheet_id}, and every
 * table without one that hangs off a person, claim, period or plan of the sheet. A table added later is
 * so kept without change here.
 */
@Service
public class SheetHistory {

    /**
     * Tables never kept: the sheet row itself is kept apart, and the snapshots are the history. The
     * sheet's notes are dated by the today each was added on, and shown as of a date by that.
     */
    private static final Set<String> SKIPPED = Set.of("SHEET", "SHEET_SNAPSHOT", "SHEET_NOTE",
            "flyway_schema_history");

    /** The sheet's columns not kept: they are not dated, so a sheet shown as of a date shows them as they are now. */
    private static final Set<String> UNKEPT_SHEET_COLUMNS = Set.of("PARENT_ID");

    /** The tables others refer to, deleted last and put back first (in this order of putting back). */
    private static final List<String> PARENTS = List.of("PERSON", "PERIOD", "CLAIM");

    /** A kept table: its name, the clause picking the sheet's rows (one parameter, the sheet's id) and its columns. */
    private record Table(String name, String where, List<String> columns) {
    }

    private final JdbcTemplate jdbc;
    private volatile List<Table> tables;
    private volatile List<String> sheetColumns;

    public SheetHistory(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Keep the sheet as the store holds it now, made on its today; nothing when there is no such sheet. */
    @Transactional
    public void capture(String sheetId) {
        // hold the sheet so no change lands between reading its rows and its today
        List<LocalDate> today = jdbc.query("SELECT today FROM sheet WHERE id = ? FOR UPDATE",
                (rs, n) -> rs.getObject(1, LocalDate.class), sheetId);
        if (today.isEmpty()) {
            return;
        }
        save(sheetId, today.get(0));
    }

    /** Keep the sheet as it is now as counting from the beginning of time, when nothing is kept for it yet. */
    @Transactional
    public void captureFirst(String sheetId) {
        if (jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, n) -> rs.getString(1), sheetId).isEmpty()) {
            return;
        }
        Long kept = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_snapshot WHERE sheet_id = ?", Long.class, sheetId);
        if (kept == null || kept == 0) {
            save(sheetId, null);
        }
    }

    /**
     * Within the caller's transaction, replace the sheet's rows by the last snapshot made on or
     * before {@code asOf} and set its today to {@code asOf}. The caller must roll back.
     */
    @Transactional
    public void restore(String sheetId, LocalDate asOf) {
        if (jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, n) -> rs.getString(1), sheetId).isEmpty()) {
            return;
        }
        List<byte[]> found = jdbc.query("SELECT data FROM sheet_snapshot WHERE sheet_id = ?"
                + " AND (made_on IS NULL OR made_on <= ?) ORDER BY seq DESC LIMIT 1",
                (rs, n) -> rs.getBytes(1), sheetId, asOf);
        Map<String, List<List<Object>>> data = found.isEmpty() ? Map.of() : read(found.get(0));
        List<Table> all = tables();
        for (int i = all.size() - 1; i >= 0; i--) {
            Table t = all.get(i);
            jdbc.update("DELETE FROM " + t.name() + " WHERE " + t.where(), sheetId);
        }
        for (Table t : all) {
            List<List<Object>> rows = data.get(t.name());
            if (rows == null || rows.isEmpty()) {
                continue;
            }
            List<String> columns = rows.get(0).stream().map(String::valueOf).toList();
            String sql = "INSERT INTO " + t.name() + " (" + String.join(", ", columns) + ") VALUES ("
                    + columns.stream().map(c -> "?").collect(Collectors.joining(", ")) + ")";
            for (List<Object> row : rows.subList(1, rows.size())) {
                jdbc.update(sql, row.toArray());
            }
        }
        List<List<Object>> sheet = data.get("SHEET");
        if (sheet != null && sheet.size() == 2) {
            List<String> columns = sheet.get(0).stream().map(String::valueOf).toList();
            List<Object> values = new ArrayList<>(sheet.get(1));
            values.add(sheetId);
            jdbc.update("UPDATE sheet SET " + columns.stream().map(c -> c + " = ?").collect(Collectors.joining(", "))
                    + " WHERE id = ?", values.toArray());
        }
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", asOf, sheetId);
        // a claim editor's lock is this moment's, not the sheet's history: no editor is open as of a date
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ?", sheetId);
    }

    /** Read the schema once the app is up, so the first change is not slowed by it. */
    @EventListener(ApplicationReadyEvent.class)
    public void warmUp() {
        tables();
        sheetColumns();
    }

    private void save(String sheetId, LocalDate madeOn) {
        LinkedHashMap<String, List<List<Object>>> data = new LinkedHashMap<>();
        data.put("SHEET", rows("SELECT " + String.join(", ", sheetColumns()) + " FROM sheet WHERE id = ?", sheetId));
        for (Table t : tables()) {
            data.put(t.name(), rows("SELECT " + String.join(", ", t.columns()) + " FROM " + t.name() + " WHERE "
                    + t.where(), sheetId));
        }
        jdbc.update("INSERT INTO sheet_snapshot (sheet_id, made_on, data) VALUES (?, ?, ?)", sheetId, madeOn,
                write(data));
    }

    /** The rows a query returns, the first the column names. */
    private List<List<Object>> rows(String sql, String sheetId) {
        return jdbc.query(sql, (ResultSet rs) -> {
            ResultSetMetaData meta = rs.getMetaData();
            List<List<Object>> rows = new ArrayList<>();
            List<Object> names = new ArrayList<>();
            for (int i = 1; i <= meta.getColumnCount(); i++) {
                names.add(meta.getColumnName(i));
            }
            rows.add(names);
            while (rs.next()) {
                List<Object> row = new ArrayList<>();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.add(rs.getObject(i));
                }
                rows.add(row);
            }
            return rows;
        }, sheetId);
    }

    /**
     * The sheet's columns that can be set (all but its id and generated ones), less those that have no
     * history: its parent is shown as of a date as it is now.
     */
    private List<String> sheetColumns() {
        if (sheetColumns == null) {
            sheetColumns = columns("SHEET").stream().filter(c -> !c.equals("ID") && !UNKEPT_SHEET_COLUMNS.contains(c))
                    .toList();
        }
        return sheetColumns;
    }

    /** The kept tables, those others refer to first. */
    private List<Table> tables() {
        if (tables != null) {
            return tables;
        }
        List<String> names = jdbc.queryForList("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES"
                + " WHERE TABLE_SCHEMA = 'PUBLIC' AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME", String.class);
        List<Table> found = new ArrayList<>();
        for (String parent : PARENTS) {
            found.add(new Table(parent, "sheet_id = ?", columns(parent)));
        }
        for (String name : names) {
            if (SKIPPED.contains(name) || PARENTS.contains(name)) {
                continue;
            }
            List<String> columns = columns(name);
            // a period's rows go by the period they refer to, also those naming a person since merged away
            String where = columns.contains("SHEET_ID") ? "sheet_id = ?"
                    : columns.contains("PERIOD_ID") ? "period_id IN (SELECT id FROM period WHERE sheet_id = ?)"
                    : columns.contains("PERSON_ID") ? "person_id IN (SELECT id FROM person WHERE sheet_id = ?)"
                    : columns.contains("CLAIM_ID") ? "claim_id IN (SELECT id FROM claim WHERE sheet_id = ?)"
                    : columns.contains("PLAN_ID") ? "plan_id IN (SELECT id FROM plan WHERE sheet_id = ?)"
                    : null;
            if (where != null) {
                found.add(new Table(name, where, columns));
            }
        }
        tables = List.copyOf(found);
        return tables;
    }

    /** A table's columns that are stored (not generated), in order. */
    private List<String> columns(String table) {
        return jdbc.queryForList("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'PUBLIC'"
                + " AND TABLE_NAME = ? AND IS_GENERATED = 'NEVER' ORDER BY ORDINAL_POSITION", String.class, table);
    }

    private static byte[] write(LinkedHashMap<String, List<List<Object>>> data) {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(data);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return bytes.toByteArray();
    }

    @SuppressWarnings("unchecked")
    private static Map<String, List<List<Object>>> read(byte[] data) {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (Map<String, List<List<Object>>>) in.readObject();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } catch (ClassNotFoundException e) {
            throw new IllegalStateException(e);
        }
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * One line of a sheet's setting log: a value recorded for a setting from a from-date, and the
 * sheet's today when it was recorded (none: from the beginning of time).
 */
@Embeddable
public class LoggedSetting {

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "amount", precision = 14, scale = 2)
    private BigDecimal value;

    @Column(name = "made_on")
    private LocalDate madeOn;

    protected LoggedSetting() {
    }

    public LoggedSetting(String key, LocalDate fromDate, BigDecimal value, LocalDate madeOn) {
        this.key = key;
        this.fromDate = fromDate;
        this.value = value;
        this.madeOn = madeOn;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public BigDecimal getValue() {
        return value;
    }

    /** Whether it was recorded by the end of a day: the sheet's today then on or before it. */
    public boolean madeBy(LocalDate day) {
        return madeOn == null || !madeOn.isAfter(day);
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import jakarta.servlet.http.HttpServletResponse;
import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Optional;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;
import org.springframework.web.filter.OncePerRequestFilter;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/**
 * The as-of view. A screen showing the sheet as of a date sends it on every request in the
 * {@value #HEADER} header. Such a request that only reads is answered from the sheet as it stood at
 * the end of that date (see {@link SheetHistory}), its today the date, in a transaction that is then
 * rolled back, so nothing it does is kept or audited; any other is refused (423) and changes nothing.
 * Without the header a request is served as it is, and once a change has been made the sheet is kept
 * as it now stands (taking or releasing a claim editor's lock is no change to keep).
 */
@Component
public class AsOfFilter extends OncePerRequestFilter {

    public static final String HEADER = "X-As-Of";

    /** The request attribute holding the date a request is answered as of; absent when it is answered as it is now. */
    public static final String AS_OF = AsOfFilter.class.getName() + ".asOf";

    private static final String LOAD = "/api/sheets/load";

    /**
     * The requests that only read the sheet (with every path ending in {@code /list}); saving the
     * user's locale is no change to any sheet, so it goes through as-of too.
     */
    private static final Set<String> READS = Set.of("/api/signin", LOAD, "/api/settings/get", "/api/users/locale",
            "/api/people/watched", "/api/roles/delegations", "/api/claims/tags");

    /**
     * The reads answered as the store holds the sheets now, whatever the date asked for: the tree
     * search is not dated. (The consolidated figures are: each sheet of the tree as it stood then.)
     */
    private static final Set<String> UNDATED = Set.of("/api/search/tree/list");

    /** The changes that only take or release a claim editor's lock: not part of the sheet's history. */
    private static final Set<String> LOCKS = Set.of("/api/claims/lock", "/api/claims/unlock");

    private final SheetHistory history;
    private final SheetService sheets;
    private final TransactionTemplate rolledBack;
    private final JsonMapper json;

    public AsOfFilter(SheetHistory history, SheetService sheets, PlatformTransactionManager transactions,
            JsonMapper json) {
        this.history = history;
        this.sheets = sheets;
        this.rolledBack = new TransactionTemplate(transactions);
        this.json = json;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !"POST".equals(request.getMethod()) || !request.getRequestURI().startsWith("/api/");
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        Body body = new Body(request);
        String path = request.getRequestURI();
        boolean read = READS.contains(path) || path.endsWith("/list");
        String sheet = body.sheet();
        String header = request.getHeader(HEADER);
        LocalDate asOf = null;
        if (header != null && !header.isBlank()) {
            try {
                asOf = LocalDate.parse(header.trim());
            } catch (DateTimeParseException e) {
                response.sendError(HttpStatus.BAD_REQUEST.value(), "Not a date: " + header);
                return;
            }
        }
        if (asOf == null) {
            chain.doFilter(body, response);
            if (sheet != null && path.equals(LOAD)) {
                history.captureFirst(sheet);
            } else if (sheet != null && !read && !LOCKS.contains(path)) {
                history.capture(sheet);
            }
            return;
        }
        if (!read) {
            response.sendError(HttpStatus.LOCKED.value(), "The sheet is shown as of a date and may not be changed.");
            return;
        }
        if (sheet == null || UNDATED.contains(path)) {
            chain.doFilter(body, response);
            return;
        }
        if (path.equals(LOAD)) {
            // a sheet never loaded starts as usual, and counts from the beginning of time
            String user = body.field("user");
            String open = body.field("open");
            sheets.load(sheet, user == null || user.isBlank() ? "?" : user.trim(),
                    open == null || open.isBlank() ? null : open.trim());
            history.captureFirst(sheet);
        }
        LocalDate date = asOf;
        body.setAttribute(AS_OF, date);
        try {
            rolledBack.executeWithoutResult(status -> {
                status.setRollbackOnly();
                history.restore(sheet, date);
                try {
                    chain.doFilter(body, response);
                } catch (IOException | ServletException e) {
                    throw new IllegalStateException(e);
                }
            });
        } catch (IllegalStateException e) {
            if (e.getCause() instanceof IOException io) {
                throw io;
            }
            if (e.getCause() instanceof ServletException se) {
                throw se;
            }
            throw e;
        }
    }

    /**
     * The date the current request is answered as of; empty when it is answered as it is now. Only the
     * sheet the request is about is restored as it stood then: what another sheet held then must be
     * read from its own history with this date.
     */
    public static Optional<LocalDate> current() {
        return RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs
                && attrs.getRequest().getAttribute(AS_OF) instanceof LocalDate date ? Optional.of(date) : Optional.empty();
    }

    /** The request with its body read once, so both this filter and the handler can read it. */
    private final class Body extends HttpServletRequestWrapper {

        private final byte[] bytes;
        private JsonNode node;

        Body(HttpServletRequest request) throws IOException {
            super(request);
            this.bytes = request.getInputStream().readAllBytes();
        }

        /** The sheet the request is about: its {@code sheet}, or {@code id} for the sheet's own requests. */
        String sheet() {
            String sheet = field("sheet");
            if (sheet == null && getRequestURI().startsWith("/api/sheets/")) {
                sheet = field("id");
            }
            return sheet == null || sheet.isBlank() ? null : sheet.trim();
        }

        String field(String name) {
            if (node == null) {
                try {
                    node = json.readTree(bytes);
                } catch (RuntimeException e) {
                    return null;
                }
            }
            JsonNode value = node == null ? null : node.get(name);
            return value == null || !value.isString() ? null : value.asString();
        }

        @Override
        public ServletInputStream getInputStream() {
            ByteArrayInputStream in = new ByteArrayInputStream(bytes);
            return new ServletInputStream() {
                @Override
                public int read() {
                    return in.read();
                }

                @Override
                public int read(byte[] b, int off, int len) {
                    return in.read(b, off, len);
                }

                @Override
                public boolean isFinished() {
                    return in.available() == 0;
                }

                @Override
                public boolean isReady() {
                    return true;
                }

                @Override
                public void setReadListener(ReadListener listener) {
                    throw new UnsupportedOperationException();
                }
            };
        }

        @Override
        public BufferedReader getReader() {
            return new BufferedReader(new InputStreamReader(getInputStream(), StandardCharsets.UTF_8));
        }
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** One of a person's holds: from its from-date to its to-date (none: open-ended), both inclusive. */
@Embeddable
public class DatedHold {

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    /** The sheet's today when it was recorded; none: from the beginning of time. */
    @Column(name = "made_on")
    private LocalDate madeOn;

    protected DatedHold() {
    }

    public DatedHold(LocalDate fromDate, LocalDate toDate, LocalDate madeOn) {
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.madeOn = madeOn;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the day lies within the hold. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(fromDate) && (toDate == null || !date.isAfter(toDate));
    }

    /** Whether it was recorded by the end of a day: the sheet's today then on or before it. */
    public boolean madeBy(LocalDate day) {
        return madeOn == null || !madeOn.isAfter(day);
    }
}
