          @for (p of memberPools(); track p.id) {
            <option [value]="'pool:' + p.id" [selected]="personInput() === 'pool:' + p.id">pool:{{ p.name }}</option>
          }
        </select>
        <label [for]="'pool-member-share-' + pool().id">Share %</label>
        <input
          [id]="'pool-member-share-' + pool().id"
